def count_distinct_product_primes(nums):
    factors=set()
    for value in nums:
        divisor=2
        while divisor*divisor<=value:
            if value%divisor==0:
                factors.add(divisor)
                while value%divisor==0:value//=divisor
            divisor+=1
        if value>1:factors.add(value)
    return len(factors)

